                        // A failure reads at full strength.
                        ToolState::Failed => state.font_medium(),
                        IconName::ChevronRight
                    })
                    .label(label)
                    .disabled(!enabled)
                    .on_click(cx.listener(move |this, _, _, cx| {
                        select(this).toggle();
                        cx.notify();
                    })),
            )
            .into_any_element()
    }

    /// Every item, oldest first, as an accordion that scrolls.
